-- Request codes: number the new demo requests per Lima calendar year, in creation order, after the last code
-- already issued that year, and move request_code_sequences forward so the application never repeats a code.
CREATE TEMPORARY TABLE demo_codes (
  request_id BIGINT PRIMARY KEY,
  code_year INT NOT NULL,
  position_in_year INT NOT NULL
);

SELECT id, YEAR(created_at - INTERVAL 5 HOUR),
       ROW_NUMBER() OVER (PARTITION BY YEAR(created_at - INTERVAL 5 HOUR) ORDER BY created_at, id)
  FROM service_requests
 WHERE code LIKE 'DEMO-%';

UPDATE service_requests r
  JOIN demo_codes d ON d.request_id = r.id
  LEFT JOIN request_code_sequences s ON s.seq_year = d.code_year
   SET r.code = CONCAT('SOL-', d.code_year, '-', LPAD(COALESCE(s.`last_value`, 0) + d.position_in_year, 6, '0'));

SELECT * FROM (
  SELECT CAST(SUBSTRING(code, 5, 4) AS UNSIGNED) AS seq_year, MAX(CAST(SUBSTRING(code, 10) AS UNSIGNED)) AS max_value
    FROM service_requests
   WHERE code LIKE 'SOL-____-______'
   GROUP BY CAST(SUBSTRING(code, 5, 4) AS UNSIGNED)
) AS issued
ON DUPLICATE KEY UPDATE `last_value` = GREATEST(request_code_sequences.`last_value`, issued.max_value);

DROP TEMPORARY TABLE demo_codes;

-- Notifications of the last two weeks (those before yesterday are read). Their text quotes the final request code,
-- so they are staged first and joined with service_requests.
CREATE TEMPORARY TABLE demo_notifications (
  id BIGINT PRIMARY KEY,
  recipient_id BIGINT NOT NULL,
  request_id BIGINT NOT NULL,
  text_before VARCHAR(200) NOT NULL,
  text_after VARCHAR(200) NOT NULL,
  read_at DATETIME(6) NULL,
  created_at DATETIME(6) NOT NULL
);


SELECT d.id, d.recipient_id, d.request_id, CONCAT(d.text_before, r.code, d.text_after), d.read_at, d.created_at
  FROM demo_notifications d
  JOIN service_requests r ON r.id = d.request_id
ON DUPLICATE KEY UPDATE notifications.id = notifications.id;

DROP TEMPORARY TABLE demo_notifications;
